SELECT p.subject_id, ph.pharmacy_id, ph.infusion_type, ph.sliding_scale, COUNT(*)::FLOAT / NULLIF(SUM(CASE WHEN a.admittime <= 48 THEN 1 ELSE 0 END) + SUM(CASE WHEN a.dischtime >= 48 THEN 1 ELSE 0 END) + SUM(CASE WHEN t.transfertime BETWEEN 0 AND 48 THEN 1 ELSE 0 END), 0) AS proportion FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN pharmacy ph ON a.subject_id = ph.subject_id JOIN transfers t ON a.subject_id = t.subject_id AND a.hadm_id = t.hadm_id WHERE p.gender = 'F' AND EXTRACT(YEAR FROM age(CURRENT_DATE, p.dob)) = 70 AND a.admittime BETWEEN 65 AND 75 AND a.length_of_stay >= 96 AND (ph.infusion_type = 'basal' OR ph.infusion_type = 'bolus' OR ph.infusion_type = 'basal-bolus' OR ph.sliding_scale = TRUE) GROUP BY p.subject_id, ph.pharmacy_id, ph.infusion_type, ph.sliding_scale ORDER BY proportion DESC NULLS LAST;